/* 01-runtime.js */
/* Manifesto PWA gerado em tempo de execução (arquivo único, sem arquivos externos) */
    (function(){
      try {
        if (location.protocol === 'http:' || location.protocol === 'https:') {
          var manifestLink=document.querySelector('link[rel="manifest"]');
          if(!manifestLink){manifestLink=document.createElement('link');manifestLink.rel='manifest';document.head.appendChild(manifestLink)}
          manifestLink.href='./manifest.webmanifest';return;
        }
        var I192="data:image/png;base64,",
            I512="data:image/png;base64,",
            IMSK="data:image/png;base64,";
        var base=location.href.split('#')[0].split('?')[0];
        var manifest={
          id:base, name:"EvoluFísico", short_name:"EvoluFísico",
          description:"Avaliação física e composição corporal.",
          start_url:base, scope:base.replace(/[^\/]*$/,''),
          display:"standalone", orientation:"any",
          background_color:"#0f172a", theme_color:"#f2f2f7", lang:"pt-BR",
          icons:[
            {src:I192,sizes:"192x192",type:"image/png",purpose:"any"},
            {src:I512,sizes:"512x512",type:"image/png",purpose:"any"},
            {src:IMSK,sizes:"512x512",type:"image/png",purpose:"maskable"}
          ]
        };
        var url=URL.createObjectURL(new Blob([JSON.stringify(manifest)],{type:"application/manifest+json"}));
        var l=document.createElement("link"); l.rel="manifest"; l.href=url;
        document.head.appendChild(l);
      } catch(e) { console.warn("Manifest PWA não criado:", e); }
    })();
